            "trigger_f1": f1(t_tp, len(doc_stats["gold_triggers"]), len(doc_stats["pred_triggers"])),
            "argument_f1": f1(a_tp, len(doc_stats["gold_args"]), len(doc_stats["pred_args"])),
            "rov": doc_stats["rov_violations"] / doc_stats["total_pred_arguments"] if doc_stats["total_pred_arguments"] else 0.0,
            "ac": doc_stats["ac_violations"] / doc_stats["total_pred_arguments"] if doc_stats["total_pred_arguments"] else 0.0,
            "n_gold_triggers": len(doc_stats["gold_triggers"]), "n_pred_triggers": len(doc_stats["pred_triggers"]),
            "n_gold_args": len(doc_stats["gold_args"]), "n_pred_args": len(doc_stats["pred_args"])}

def compute_aggregate_metrics(doc_stats_list):
    t_tp = t_gold = t_pred = a_tp = a_gold = a_pred = total_rov = total_ac = total_args = pf = 0
    n = len(doc_stats_list)
    for ds in doc_stats_list:
        if ds["parse_failed"]: pf += 1; continue
        t_tp += len(ds["gold_triggers"] & ds["pred_triggers"]); t_gold += len(ds["gold_triggers"]); t_pred += len(ds["pred_triggers"])
        a_tp += len(ds["gold_args"] & ds["pred_args"]); a_gold += len(ds["gold_args"]); a_pred += len(ds["pred_args"])
        total_rov += ds["rov_violations"]; total_ac += ds["ac_violations"]; total_args += ds["total_pred_arguments"]
    return {"trigger_f1": f1(t_tp, t_gold, t_pred), "argument_f1": f1(a_tp, a_gold, a_pred),
            "rov": total_rov / total_args if total_args else 0.0, "ac": total_ac / total_args if total_args else 0.0,
            "parse_rate": 1.0 - pf / n if n else 0.0}

def bootstrap_ci(doc_stats_list):
    rng = random.Random(SEED); n = len(doc_stats_list)
    point = compute_aggregate_metrics(doc_stats_list)
    metric_names = ["trigger_f1", "argument_f1", "rov", "ac"]
    samples = {m: [] for m in metric_names}
    for _ in range(B):
        resampled = [doc_stats_list[rng.randint(0, n - 1)] for _ in range(n)]
        metrics = compute_aggregate_metrics(resampled)
        for m in metric_names: samples[m].append(metrics[m])
    result = {}
    for m in metric_names:
        s = sorted(samples[m])
        result[m] = {"mean": round(sum(s)/len(s), 4), "ci_lower": round(percentile(s, CI_LOWER_PCT), 4),
                      "ci_upper": round(percentile(s, CI_UPPER_PCT), 4), "point": round(point[m], 4)}
    result["parse_rate"] = round(point["parse_rate"], 4)
    return result

def summary_stats(values):
    n = len(values)
    if n == 0: return {"mean": 0, "std": 0, "median": 0, "iqr": [0, 0], "min": 0, "max": 0, "n": 0}
    mean = sum(values) / n; std = math.sqrt(sum((x - mean)**2 for x in values) / n)
    s = sorted(values); median = s[n//2] if n%2==1 else (s[n//2-1]+s[n//2])/2
    return {"mean": round(mean,4), "std": round(std,4), "median": round(median,4),
            "iqr": [round(percentile(s,25),4), round(percentile(s,75),4)],
            "min": round(min(values),4), "max": round(max(values),4), "n": n}

def analyze_file(file_path, constraints):
    path = Path(file_path)
    if not path.exists(): return None
    records = []
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if line:
                try: records.append(json.loads(line))
                except json.JSONDecodeError: continue
    doc_stats_list = [compute_doc_stats(r, constraints) for r in records]
    per_doc = [m for ds in doc_stats_list if (m := compute_per_doc_metrics(ds)) is not None]
    ci = bootstrap_ci(doc_stats_list)
    metrics = {}
    for metric_name in ["trigger_f1", "argument_f1", "rov", "ac"]:
        values = [d[metric_name] for d in per_doc]
        stats = summary_stats(values)
        stats["ci_95"] = [ci[metric_name]["ci_lower"], ci[metric_name]["ci_upper"]]
        stats["point_micro"] = ci[metric_name]["point"]
        stats["per_doc"] = [{"doc_id": d["doc_id"], "value": round(d[metric_name], 4)} for d in per_doc]
        metrics[metric_name] = stats
    metrics["parse_rate"] = ci["parse_rate"]
    metrics["n_docs_total"] = len(doc_stats_list)
    metrics["n_docs_parsed"] = len(per_doc)
    return metrics

def main():
    config = json.loads(sys.argv[1])
    constraints = load_ontology(ONTOLOGY_PATH)
    result = {config["model_name"]: {}}
    for mode_name, file_path in config["files"].items():
        metrics = analyze_file(file_path, constraints)
        if metrics is None: continue
        result[config["model_name"]][mode_name] = metrics
        print(f"{config['model_name']}/{mode_name}: {metrics['n_docs_total']} docs, {metrics['n_docs_parsed']} parsed", file=sys.stderr)
    print(json.dumps(result, indent=2, ensure_ascii=False))

if __name__ == "__main__": main()
